from taf.ul.sc import perf
from taf.ul.sc.perf.tc import tc_params
from taf.ul.sc.perf.tc import execution_stats
from taf.ul.sc.perf.util.helpers import ClassProperty
from taf.ul.sc.perf.util.logger import log_info_to_console


class tc(object):
    """
    Class keeps some of automatic variable useful during test execution - mainly for post processing.
    """
    run_params = tc_params._run_params
    stats = execution_stats._stats

    @staticmethod
    def load_run_params(test_case_params, golden_params):
        tc_params.load_run_params(test_case_params, golden_params)

    @staticmethod
    def add_stats(stats, print_markers=True, stats_type='marker'):
        execution_stats.add_stats(stats, print_markers, stats_type)

    @ClassProperty
    def output_dir(self):
        return tc.run_params['output_dir']

    @ClassProperty
    def scenario_name(self):
        return tc.run_params['scenario_name']

    @ClassProperty
    def test_case_name(self):
        return tc.run_params['test_case_name']

    @ClassProperty
    def tester_username(self):
        tester_username = tc.stats['DB']['string properties'].get('tester username', None)
        if not tester_username and "tester_username" in tc.run_params:
            tester_username = tc.run_params['tester_username']
        if not tester_username:
            log_info_to_console("Tester username is not set. Set it in you .env file (parameter tester_username)")
            tester_username = self.test_line_owner
        return tester_username

    @ClassProperty
    def database_permalink(self):
        return tc.stats['DB']['permalink']

    @ClassProperty
    def database_id(self):
        return tc.stats['DB']['id']

    @ClassProperty
    def execution_date(self):
        return tc.stats['DB']['string properties']['execution date']

    @ClassProperty
    def test_line_name(self):
        return tc.stats['DB']['string properties']['test line']

    @ClassProperty
    def test_line_owner(self):
        return tc.stats['DB']['string properties'].get('test line owner', None)

    @ClassProperty
    def test_line_maintainers(self):
        return tc.stats['DB']['string properties'].get('test line maintainers', None)

    @ClassProperty
    def bts_release(self):
        return tc.stats['DB']['string properties']['bts release']

    @ClassProperty
    def bts_build(self):
        return tc.stats['DB']['string properties']['bts build']

    @ClassProperty
    def current_test_case_status(self):
        return tc.stats['DB']['enumerated properties']['status']

    @ClassProperty
    def validation_url_link(self):
        return tc.stats['DB']['string properties']['validation url']

    @ClassProperty
    def start_test_timestamp(self):
        return tc.stats['DB']['integer properties']['start test timestamp']

    @ClassProperty
    def stop_test_timestamp(self):
        return tc.stats['DB']['integer properties']['stop test timestamp']

    @ClassProperty
    def logs_url(self):
        return tc.stats['DB']['string properties']['logs url']

    @staticmethod
    def is_feature_enabled(feature_name):
        """
        Checking if passed feature is enable or disable.

        :param feature_name: Could be passed as single name eg: 'validate_test_results'
                             or as nested feature like 'validate_test_results->TEB' - in this case check if all
                             nested features are enabled
        :return: True/False
        """
        statuses = []
        run_params = tc.run_params
        features = feature_name.split("->")

        for feature in features:
            statuses.append(run_params[feature]['enabled'])
            run_params = run_params[feature]

        return all(statuses)

    @staticmethod
    def required_btss():
        """
        BTSs generator
        """
        bts_names = tc.run_params['require_bts']
        for bts in perf.tl.btss:
            if bts_names and bts.name not in bts_names:
                continue
            yield bts
